/**
 * Every sound in the game (Phase 14 audio): one list that drives the engine,
 * `docs/audio/sound-list.md` (generated by tools/audio/sound-list.ts) and the
 * sound board (`?scene=sounds`).
 *
 * File slots: a sound `ant.bite` with 5 takes looks for
 * `public/audio/ant/bite_01.ogg` … `bite_05.ogg` (and `.m4a` for Safari).
 * `npm run audio:manifest` records which files exist; any sound without
 * files plays its organic stand-in (`recipe`, in standins.ts), so files can be
 * added one at a time with no code changes.
 */

export type Bus = 'ambience' | 'creatures' | 'combat' | 'ui' | 'music' | 'narration';

export interface SoundDef {
  id: string;
  bus: Bus;
  /** section of the sound list */
  group: string;
  /** what it should sound like */
  desc: string;
  /** typical length */
  dur: string;
  /** variations wanted (file takes); stand-ins render this many */
  takes: number;
  /** level in the mix (0–1) */
  gain: number;
  /** random pitch, ± fraction (0.08 = ±8 %) */
  pitch: number;
  /** random volume, ± fraction */
  vol: number;
  /** most voices of this sound at once */
  voices: number;
  /** a looping bed (ambience, swarm textures) */
  loop?: boolean;
  /** long file: streamed, not decoded whole (music, long ambience) */
  stream?: boolean;
  /** stand-in recipe (standins.ts); music stems have none (the procedural score plays instead) */
  recipe?: string;
  /** suggested search terms for libraries and Freesound */
  search: string[];
  /** how to record it yourself */
  foley: string;
  /** not used by the game yet (a species, creature or feature still to come) */
  reserved?: string;
  /** the stand-in has no high content: keep it at 1/2 or 1/4 of the sample rate (memory) */
  down?: 2 | 4;
}

const d = (
  id: string,
  bus: Bus,
  group: string,
  desc: string,
  o: Partial<SoundDef> & { search: string[]; foley: string; dur: string },
): SoundDef => ({ id, bus, group, desc, takes: 5, gain: 0.7, pitch: 0.07, vol: 0.15, voices: 4, recipe: id.split('.')[1], ...o });

