export const SOUND: Record<string, SoundDef> = Object.fromEntries(SOUNDS.map((s) => [s.id, s]));

/** The file path of take `n` (1-based) of a sound, without extension: `ant/bite_01`. */
export function takePath(id: string, n: number): string {
  const [folder, name] = id.split('.');
  return `${folder}/${name}_${String(n).padStart(2, '0')}`;
}
